import type { AssistantRuntime, SuggestionAdapter, ThreadMessage, ThreadSuggestion } from "@assistant-ui/react";
import { useEffect, useState } from "react";
import type { ContextEntry } from "@/lib/agents";
import type { Api } from "@/lib/api";

// Follow-up suggestions after each reply, generated by the model in the api
// process (agent/src/suggestions.py), which owns the prompt.
//
// This is assistant-ui's SuggestionAdapter, but useAgUiRuntime doesn't take
// one (only its local runtime runs adapters.suggestion), so
// useFollowUpSuggestions below calls it when a run settles, the way the local
// runtime would.

const text = (m: ThreadMessage) =>
  m.content
    .map((p) => (p.type === "text" ? p.text : ""))
    .join("")
    .trim();

/** `tools` are the chat's frontend tools, so the suggestions can include
 * what they do; the server adds the agent's own. */
export function createFollowUpAdapter({
  api,
  getContext,
  tools,
}: {
  api: Api;
  getContext: () => ContextEntry[];
  tools: { name: string; description: string }[];
}): SuggestionAdapter {
  return {
    async generate({ messages, signal }) {
      const prompts = await api.suggestions(
        {
          messages: messages.map((m) => ({ role: m.role, text: text(m) })).filter((m) => m.text),
          tools,
          screen: getContext()
            .map((c) => `${c.description}: ${c.value}`)
            .join("\n"),
        },
        signal,
      );
      return prompts.map((prompt) => ({ prompt }));
    },
  };
}

/** Suggestions for the reply that just finished, or none while a run is going
 * or once the thread is cleared. */
export function useFollowUpSuggestions(runtime: AssistantRuntime, adapter: SuggestionAdapter) {
  const [suggestions, setSuggestions] = useState<readonly ThreadSuggestion[]>([]);
  useEffect(() => {
    let controller: AbortController | null = null;
    let wasRunning = runtime.thread.getState().isRunning;
    const stop = () => {
      controller?.abort();
      controller = null;
    };
    const unsubscribe = runtime.thread.subscribe(() => {
      const { isRunning, messages } = runtime.thread.getState();
      if (isRunning || messages.length === 0) {
        stop();
        setSuggestions((s) => (s.length ? [] : s));
      }
      const settled = wasRunning && !isRunning;
      wasRunning = isRunning;
      const last = messages.at(-1);
      // A run that ended to hand a browser tool its call is followed by
      // another run; only a finished reply gets suggestions.
      if (!settled || last?.role !== "assistant" || last.status?.type !== "complete" || !text(last)) return;
      stop();
      const mine = (controller = new AbortController());
      const show = (next: readonly ThreadSuggestion[]) => controller === mine && setSuggestions(next);
      (async () => {
        const result = adapter.generate({ messages, signal: mine.signal });
        if (Symbol.asyncIterator in result) for await (const next of result) show(next);
        else show(await result);
      })().catch(() => {}); // aborted, or the request failed: no suggestions
    });
    return () => {
      unsubscribe();
      stop();
    };
  }, [runtime, adapter]);
  return suggestions;
}
